templates.home:
{{if .theme.boutique}}{{template "home_boutique" .}}{{else}}{{template "top" .}}{{if .theme.lux}}<section class="hero{{if .store.hero_image}} has-photo{{end}}">{{with .store.hero_image}}<img class="hero-img" src="{{.}}?w=1600" srcset="{{.}}?w=800 800w, {{.}}?w=1200 1200w, {{.}}?w=1600 1600w, {{.}}?w=2000 2000w" sizes="100vw" alt="" fetchpriority="high">{{end}}
<div class="hero-text"><h1>{{if .tagline}}{{.tagline}}{{else}}{{.storeName}}{{end}}</h1>{{if .products}}<a class="cta" href="#products">{{.t.shop_now}}</a>{{end}}</div></section>
{{with .story}}<section class="story"><div class="wrap"><p>{{.}}</p></div></section>{{end}}
<section class="collection" id="products" aria-labelledby="collection-h"><div class="wrap"><h2 id="collection-h">{{.t.collection}}</h2>{{else}}<section class="intro{{if .store.hero_image}} has-photo{{end}}"><div class="wrap"><div class="intro-text"><h1>{{if .tagline}}{{.tagline}}{{else}}{{.storeName}}{{end}}</h1>{{if .products}}<a class="btn on-brand" href="#products">{{.t.shop_now}}</a>{{end}}</div>{{with .store.hero_image}}<div class="intro-photo"><img src="{{.}}?w=960" srcset="{{.}}?w=480 480w, {{.}}?w=960 960w" sizes="(min-width:720px) 45vw, 100vw" alt="" fetchpriority="high"></div>{{end}}</div></section>
<section class="collection"><div class="wrap">{{end}}<form class="search" role="search" action="/" method="get"><label class="vh" for="q">{{.t.search}}</label><input id="q" type="search" name="q" value="{{.q}}" placeholder="{{.t.search_hint}}" autocomplete="off" enterkeyhint="search">{{with .category}}<input type="hidden" name="c" value="{{.}}">{{end}}{{if eq .lang "ar"}}<input type="hidden" name="lang" value="ar">{{end}}</form>
{{if gt (len .categories) 1}}<nav class="cats" aria-label="{{.t.categories}}"><a href="/{{.qs}}{{if .theme.lux}}#products{{end}}"{{if not .category}} aria-current="page"{{end}}>{{.t.all}}</a>{{range .categories}}<a href="/?c={{.value}}{{$.amp}}{{if $.theme.lux}}#products{{end}}"{{if eq .value $.category}} aria-current="page"{{end}}>{{.label}}</a>{{end}}</nav>{{end}}
<div id="results" aria-live="polite">{{if .products}}<div class="tiles"{{if not .theme.lux}} id="products"{{end}}>{{range .products}}<a class="tile" href="/p/{{.id}}{{$.qs}}"><span class="well" style="view-transition-name:pimg-{{.id}}">{{if .image}}<img src="{{.image}}?w=640" srcset="{{.image}}?w=480 480w, {{.image}}?w=640 640w, {{.image}}?w=960 960w" sizes="(min-width:1080px) 25vw, (min-width:720px) 33vw, 50vw" alt="" loading="lazy">{{else}}<span class="small">{{.name}}</span>{{end}}</span>
<span class="tname">{{.name}}</span><span class="price">{{if .from}}{{$.t.from}} {{end}}{{.priceText}}</span>{{if .stockText}}<span class="stock{{if le .stock 0}} out{{end}}">{{.stockText}}</span>{{end}}</a>{{end}}</div>
{{else}}<div class="empty">{{if .q}}<h2>{{.t.no_results}}</h2><p>{{.t.no_results_hint}}</p>{{else}}<h2>{{.t.no_products}}</h2><p>{{.t.no_products_hint}}</p>{{end}}<a class="btn" href="/{{.qs}}">{{.t.all}}</a></div>{{end}}</div></div></section>
{{if .theme.lux}}{{with .store.story_image}}<section class="visit"><div class="visit-img"><img src="{{.}}?w=960" srcset="{{.}}?w=640 640w, {{.}}?w=960 960w, {{.}}?w=1200 1200w" sizes="(min-width:900px) 50vw, 100vw" alt="" loading="lazy"></div>
<div class="visit-text"><h2>{{$.t.visit_title}}</h2>{{with $.address}}<p>{{.}}</p>{{end}}{{if $.wa}}<a class="cta" href="https://wa.me/{{$.wa}}" target="_blank" rel="noopener">{{$.t.contact_whatsapp}}</a>{{end}}</div></section>{{end}}{{end}}
{{template "bottom" .}}
{{end}}

templates.product:
{{template "top" .}}{{with .product}}<div class="wrap pdp">
<div class="pdp-media">{{if gt (len .images) 1}}<div class="gal" aria-roledescription="carousel" aria-label="{{.name}}">{{range $i, $src := .images}}<div class="well"{{if eq $i 0}} style="view-transition-name:pimg-{{$.product.id}}"{{end}}><img src="{{$src}}?w=960" srcset="{{$src}}?w=640 640w, {{$src}}?w=960 960w, {{$src}}?w=1280 1280w" sizes="(min-width: 900px) 58vw, 100vw" alt="{{$.product.name}}" data-zoom="{{$src}}?w=1920"{{if ne $i 0}} loading="lazy"{{end}}></div>{{end}}</div><div class="gal-dots">{{range $i, $src := .images}}<button type="button" data-i="{{$i}}" aria-label="{{$.t.photo}}"{{if eq $i 0}} aria-current="true"{{end}}></button>{{end}}</div>{{else}}<div class="well" style="view-transition-name:pimg-{{.id}}">{{if .image}}<img src="{{.image}}?w=960" srcset="{{.image}}?w=640 640w, {{.image}}?w=960 960w, {{.image}}?w=1280 1280w" sizes="(min-width: 900px) 58vw, 100vw" alt="{{.name}}" data-zoom="{{.image}}?w=1920">{{else}}<span>{{.name}}</span>{{end}}</div>{{end}}</div>
<div class="pdp-info"><h1>{{.name}}</h1><p class="pprice price" id="price">{{.priceText}}</p><p class="small quiet">{{$.t.vat_included}}</p>
{{with .description}}<p class="desc">{{.}}</p>{{end}}
{{if gt .stock 0}}<form id="buy" onsubmit="return false">
{{with $.variants}}<fieldset class="opts"><legend>{{$.t.option}}</legend><div class="opt-list">{{range .}}<label class="opt"><input type="radio" name="variant" value="{{.id}}"{{if le .stock 0}} disabled{{end}}><span>{{.name}}</span><span class="small price">{{if le .stock 0}}{{$.t.out_of_stock}}{{else}}{{.priceText}}{{end}}</span></label>{{end}}</div></fieldset>{{end}}
<div class="field qtyfield"><span class="lab" id="qty-label">{{$.t.quantity}}</span><div class="stepper"><button type="button" data-step="-1" aria-label="{{$.t.qty_less}}">−</button><input id="qty" type="number" inputmode="numeric" min="1" max="{{.stock}}" value="1" aria-labelledby="qty-label"><button type="button" data-step="1" aria-label="{{$.t.qty_more}}">+</button></div>
<span class="stock" id="few"{{if not .stockText}} hidden{{end}}>{{.stockText}}</span></div>
<div class="buybar"><span class="buybar-price price" id="bar-price" aria-hidden="true">{{.priceText}}</span><button class="btn" id="add" type="button" data-id="{{.id}}" data-max="{{.stock}}">{{$.t.add_to_cart}}</button></div>
<p id="added" class="toast" role="status" hidden>{{$.t.added}}<a href="/cart{{$.qs}}">{{$.t.view_cart}}</a></p>
</form>{{else}}<p class="stock out" style="margin-top:20px">{{$.t.out_of_stock}}</p>{{end}}
<dl class="facts"><div><dt>{{$.t.delivery}}</dt><dd>{{$.deliveryFact}}</dd></div><div><dt>{{$.t.payment}}</dt><dd>{{if $.store.card_enabled}}<span>{{$.t.pay_card}}</span>{{end}}{{if $.store.cod_enabled}}<span>{{$.t.pay_cod}}</span>{{end}}</dd></div></dl>
</div></div>{{end}}
<script>
(function(){var FEW={{.t.few_left}},vs={{.variantsJSON}};vs=vs?JSON.parse(vs):[];var b=document.getElementById('add');if(!b)return;
document.body.classList.add('has-buybar');
var qty=document.getElementById('qty'),radios=document.querySelectorAll('input[name=variant]'),few=document.getElementById('few');
function pick(){var v=null,r=document.querySelector('input[name=variant]:checked');if(!r)return null;vs.forEach(function(x){if(x.id===Number(r.value))v=x});return v}
function clamp(){var max=Number(b.dataset.max),n=Math.floor(Number(qty.value)||1);n=Math.max(1,Math.min(max,n));qty.value=n;qty.max=max;
document.querySelector('[data-step="-1"]').disabled=n<=1;document.querySelector('[data-step="1"]').disabled=n>=max}
function show(){var v=pick();if(!v)return;document.getElementById('price').textContent=v.priceText;document.getElementById('bar-price').textContent=v.priceText;b.dataset.max=v.stock;
if(few){few.hidden=v.stock>5;few.textContent=FEW.replace('{n}',v.stock)}clamp()}
for(var i=0;i<radios.length;i++){radios[i].addEventListener('change',show)}
for(var i=0;i<radios.length;i++){if(!radios[i].disabled){radios[i].checked=true;break}}
document.querySelectorAll('[data-step]').forEach(function(s){s.addEventListener('click',function(){qty.value=Number(qty.value)+Number(s.dataset.step);clamp()})});
qty.addEventListener('change',clamp);show();clamp();
b.addEventListener('click',function(){var id=Number(b.dataset.id),max=Number(b.dataset.max),v=pick(),vid=v?v.id:0;
var q=Math.max(1,Math.min(max,Math.floor(Number(qty.value)||1)));var c=rxCart(),f=null;
c.forEach(function(i){if(i.id===id&&(i.v||0)===vid)f=i});if(f){f.qty=Math.min(max,f.qty+q)}else{var it={id:id,qty:q};if(vid)it.v=vid;c.push(it)}
rxSave(c);document.getElementById('added').hidden=false;if(window.rxDrawer)rxDrawer.open()})})();
</script>{{template "bottom" .}}

templates.cart:
{{template "top" .}}<div class="wrap"><div class="page-head"><h1>{{.t.cart}}</h1></div>{{with .error}}<p class="alert" role="alert">{{.}}</p>{{end}}
<div id="empty" class="empty" hidden><h2>{{.t.empty_cart}}</h2><p>{{.t.empty_cart_hint}}</p><a class="btn" href="/{{.qs}}">{{.t.continue_shopping}}</a></div>
<div id="full" class="co" hidden>
<section aria-labelledby="items-h"><h2 id="items-h" class="sr">{{.t.cart}}</h2><ul class="lines" id="lines"></ul></section>
<aside class="co-side"><div class="sheet"><h2>{{.t.order_summary}}</h2><div class="rows">
<div class="row"><span>{{.t.subtotal}}</span><span id="subtotal"></span></div>
<div class="row"><span>{{.t.delivery}}</span><span id="delivery"></span></div>
<div class="row total"><span>{{.t.total}}</span><span id="total"></span></div>
<div class="row sub"><span>{{.t.vat_included}}</span><span id="vat"></span></div></div>
{{if .freeOver}}<p class="small quiet" id="ship-hint" style="margin-top:12px">{{.shipNote}}</p>{{end}}</div></aside>
<form class="co-main" method="post" action="/checkout"><input type="hidden" name="cart" id="cart-field"><input type="hidden" name="lang" value="{{.lang}}">
{{if not .user}}<div class="group"><h2>{{.t.checkout}}</h2><p class="quiet" style="margin:8px 0 20px">{{.t.sign_in_hint}}</p><a class="btn wide" href="/_rx/auth/login?next={{.here}}">{{.t.sign_in_to_checkout}}</a></div>{{else}}
<fieldset class="group"><legend>{{.t.contact_details}}</legend><div class="pair">
<div class="field"><label for="name">{{.t.name}}</label><input id="name" name="name" autocomplete="name" required value="{{.user.name}}"></div>
<div class="field"><label for="phone">{{.t.phone}}</label><input id="phone" name="phone" type="tel" autocomplete="tel" required value="{{.user.phone}}" placeholder="+971 50 123 4567" dir="ltr"></div></div></fieldset>
<fieldset class="group"><legend>{{.t.delivery_details}}</legend>
<div class="field"><label for="emirate">{{.t.emirate}}</label><select id="emirate" name="emirate" required>{{range .emirates}}<option value="{{.value}}">{{.label}}</option>{{end}}</select></div>
<div class="field"><label for="address">{{.t.address}}</label><textarea id="address" name="address" rows="2" autocomplete="street-address" required aria-describedby="address-hint"></textarea><span class="hint" id="address-hint">{{.t.address_hint}}</span></div>
{{if .store.preorder_days}}<div class="field"><label for="wanted_date">{{.t.wanted_date}}</label><input id="wanted_date" name="wanted_date" type="date" required min="{{.minDate}}"></div>{{end}}
<div class="field"><label for="note">{{.t.order_note}}</label><textarea id="note" name="note" rows="2" maxlength="500"></textarea></div></fieldset>
<fieldset class="group"><legend>{{.t.payment}}</legend>
{{if .store.card_enabled}}<label class="choice"><input type="radio" name="payment" value="card" checked><span>{{.t.pay_card}}<span class="hint">{{.t.pay_card_hint}}</span></span></label>{{end}}
{{if .store.cod_enabled}}<label class="choice"><input type="radio" name="payment" value="cod"{{if not .store.card_enabled}} checked{{end}}><span>{{.t.pay_cod}}<span class="hint">{{.t.pay_cod_hint}}</span></span></label>{{end}}
<div class="field" style="margin-top:16px"><label for="coupon">{{.t.coupon}}</label><input id="coupon" name="coupon" autocomplete="off" autocapitalize="characters" dir="ltr"></div></fieldset>
<button class="btn wide" id="place-order" disabled>{{.t.place_order}}</button>{{end}}</form></div></div>
<script>
(function(){var MF={{.t.money}},FREE={{.t.free}},REMOVE={{.t.remove}},LESS={{.t.qty_less}},MORE={{.t.qty_more}},Q={{.qs}};
function fmt(n){return MF.replace('{n}',(Math.round(n*100)/100).toFixed(2))}
function key(i){return i.v?i.id+'.'+i.v:String(i.id)}
function el(tag,cls,text){var e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
var c=rxCart();if(!c.length){document.getElementById('empty').hidden=false;return}
fetch('/api/products?ids='+c.map(key).join(',')+'&lang={{.lang}}').then(function(r){return r.json()}).then(function(d){
var by={};d.products.forEach(function(p){by[p.key]=p});
function render(){c=c.filter(function(i){return by[key(i)]&&by[key(i)].stock>0});c.forEach(function(i){i.qty=Math.max(1,Math.min(i.qty,by[key(i)].stock))});rxSave(c);
if(!c.length){document.getElementById('full').hidden=true;document.getElementById('empty').hidden=false;return}
var box=document.getElementById('lines');box.textContent='';var sub=0;
c.forEach(function(i){var p=by[key(i)];sub+=p.priceNum*i.qty;var li=el('li','line');
var w=el('a','well');w.href='/p/'+p.id+Q;if(p.image){var im=el('img');im.src=p.image+'?w=160';im.alt='';w.appendChild(im)}li.appendChild(w);
var n=el('a','line-name',p.title||p.name);n.href='/p/'+p.id+Q;n.style.textDecoration='none';li.appendChild(n);
li.appendChild(el('span','line-total',fmt(p.priceNum*i.qty)));
var meta=el('span','line-meta');if(p.option)meta.appendChild(el('span',null,p.option));meta.appendChild(el('span','num',fmt(p.priceNum)));meta.style.gridColumn='2 / -1';li.appendChild(meta);
var acts=el('div','line-acts');acts.style.gridColumn='2 / -1';var st=el('div','stepper sm');
var less=el('button',null,'−');less.type='button';less.setAttribute('aria-label',LESS);less.disabled=i.qty<=1;
var q=el('input');q.type='number';q.value=i.qty;q.min=1;q.max=p.stock;q.setAttribute('aria-label',{{.t.quantity}});q.readOnly=true;
var more=el('button',null,'+');more.type='button';more.setAttribute('aria-label',MORE);more.disabled=i.qty>=p.stock;
less.onclick=function(){i.qty--;render()};more.onclick=function(){i.qty++;render()};st.appendChild(less);st.appendChild(q);st.appendChild(more);acts.appendChild(st);
var rm=el('button','linkbtn',REMOVE);rm.type='button';rm.onclick=function(){c=c.filter(function(x){return key(x)!==key(i)});render()};acts.appendChild(rm);li.appendChild(acts);
box.appendChild(li)});
var del=(d.free_delivery_over>0&&sub>=d.free_delivery_over)?0:d.delivery_fee,tot=sub+del;// mirrors deliveryFor in lib/common

document.getElementById('subtotal').textContent=fmt(sub);document.getElementById('delivery').textContent=del?fmt(del):FREE;
document.getElementById('total').textContent=fmt(tot);document.getElementById('vat').textContent=fmt(tot*5/105);
var hint=document.getElementById('ship-hint');if(hint)hint.hidden=!del;
document.getElementById('cart-field').value=JSON.stringify(c);var po=document.getElementById('place-order');if(po)po.disabled=false;document.getElementById('full').hidden=false}
render()})})();
</script>{{template "bottom" .}}

templates.home_boutique:
{{template "top" .}}<section class="e-hero"><div class="wrap e-hero-in">
<div class="e-hero-text">{{with .eyebrow}}<span class="eyebrow e-eyebrow">{{.}}</span>{{end}}
<h1>{{if .tagline}}{{.tagline}}{{else}}{{.storeName}}{{end}}{{with .accent}} <em class="accent">{{.}}</em>{{end}}</h1>
{{with .intro}}<p class="lead">{{.}}</p>{{end}}{{if .products}}<a class="btn e-pill" href="#products">{{.t.shop_now}}<span class="arr" aria-hidden="true">→</span></a>{{end}}
{{if .stats}}<ul class="e-stats">{{range .stats}}<li>{{if .url}}<a href="{{.url}}"><strong>{{.n}}</strong><span>{{.label}}</span></a>{{else}}<span class="e-stat"><strong>{{.n}}</strong><span>{{.label}}</span></span>{{end}}</li>{{end}}</ul>{{end}}</div>
<div class="e-hero-media">{{with .store.hero_image}}<div class="e-oval-frame"><svg class="e-deco" viewBox="0 0 120 120" aria-hidden="true" focusable="false"><circle cx="60" cy="60" r="58"/><circle cx="60" cy="60" r="40"/></svg><div class="e-oval"><img src="{{.}}?w=960" srcset="{{.}}?w=640 640w, {{.}}?w=960 960w, {{.}}?w=1280 1280w" sizes="(min-width:900px) 32vw, 70vw" alt="" fetchpriority="high"></div></div>{{end}}</div></div>
{{if .facts}}<div class="wrap"><ul class="e-facts">{{range .facts}}<li><span class="e-ic">{{template "e_icon" .icon}}</span><span class="e-fact"><span>{{.label}}</span><strong>{{.value}}</strong></span></li>{{end}}</ul></div>{{end}}</section>
{{if gt (len .families) 1}}<nav class="cats e-fams" id="families" aria-label="{{.t.categories}}"><div class="wrap e-fams-in">{{range .families}}<a class="e-fam" href="/?c={{.value}}{{$.amp}}#products"{{if eq .value $.category}} aria-current="page"{{end}}><span class="e-round">{{with .image}}<img src="{{.}}?w=320" srcset="{{.}}?w=160 160w, {{.}}?w=320 320w" sizes="96px" alt="" loading="lazy">{{end}}</span><span class="e-fam-text"><span class="e-fam-name">{{.label}}</span><span class="e-fam-n">{{.n}}</span></span></a>{{end}}</div></nav>{{end}}
<section class="collection e-featured" id="products" aria-labelledby="feat-h"><div class="wrap">
<div class="e-feat-head"><div><span class="eyebrow">{{.t.signature}}</span><h2 id="feat-h">{{.t.featured}}</h2></div>
<form class="search e-search" role="search" action="/" method="get"><label class="vh" for="q">{{.t.search}}</label><input id="q" type="search" name="q" value="{{.q}}" placeholder="{{.t.search_hint}}" autocomplete="off" enterkeyhint="search">{{with .category}}<input type="hidden" name="c" value="{{.}}">{{end}}{{if eq .lang "ar"}}<input type="hidden" name="lang" value="ar">{{end}}</form>{{if .category}}<a class="e-all" href="/{{.qs}}#products">{{.t.view_all}}<span class="arr" aria-hidden="true">→</span></a>{{end}}</div>
<div id="results" aria-live="polite">{{if .products}}<div class="e-grid">{{range .products}}<div class="e-prod"><a class="e-prod-link" href="/p/{{.id}}{{$.qs}}"><span class="e-ph" style="view-transition-name:pimg-{{.id}}">{{with .badgeText}}<span class="e-badge">{{.}}</span>{{end}}{{if .image}}<img src="{{.image}}?w=480" srcset="{{.image}}?w=320 320w, {{.image}}?w=480 480w, {{.image}}?w=640 640w" sizes="(min-width:1000px) 22vw, 46vw" alt="" loading="lazy">{{end}}</span>
{{with .categoryLabel}}<span class="e-cat">{{.}}</span>{{end}}<span class="tname">{{.name}}</span><span class="price">{{if .from}}{{$.t.from}} {{end}}{{.priceText}}</span>{{with .stockText}}<span class="e-stock">{{.}}</span>{{end}}</a>
{{if and (not .hasVariants) (gt .stock 0)}}<button class="e-add" type="button" data-add="{{.id}}" aria-label="{{$.t.add_to_cart}}: {{.name}}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 8h12l-1 12H7L6 8Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></svg></button>{{end}}</div>{{end}}</div>
{{else}}<div class="empty">{{if .q}}<h2>{{.t.no_results}}</h2><p>{{.t.no_results_hint}}</p>{{else}}<h2>{{.t.no_products}}</h2><p>{{.t.no_products_hint}}</p>{{end}}<a class="btn" href="/{{.qs}}">{{.t.all}}</a></div>{{end}}</div></div></section>
{{with .promo}}<section class="e-promo" aria-labelledby="promo-h"><div class="wrap e-promo-in">{{with .image}}<div class="e-promo-media"><img src="{{.}}?w=320" srcset="{{.}}?w=160 160w, {{.}}?w=320 320w" sizes="132px" alt="" loading="lazy"></div>{{end}}
<div class="e-promo-text"><span class="eyebrow">{{$.t.limited_offer}}</span><p class="e-promo-big" id="promo-h">{{.big}}</p><p>{{.line}}</p></div><a class="btn light e-pill" href="#products">{{$.t.shop_sale}}<span class="arr" aria-hidden="true">→</span></a>
<svg class="stamp e-stamp" viewBox="0 0 120 120" aria-hidden="true" focusable="false"><circle cx="60" cy="60" r="58"/><g class="stamp-rot"><path id="e-stamp-c" d="M60,60 m-43,0 a43,43 0 1,1 86,0 a43,43 0 1,1 -86,0" fill="none"/><text><textPath href="#e-stamp-c">{{$.stampText}}</textPath></text></g><g class="stamp-mark" transform="translate(48 48)"><path d="M12 4c2 3 2 6 0 9-2-3-2-6 0-9Z"/><path d="M12 13c3-2 6-2 8 0-3 2-6 2-8 0ZM12 13c-3-2-6-2-8 0 3 2 6 2 8 0Z"/><path d="M12 13v7"/></g></svg></div></section>{{end}}
{{if .arrivals}}<section class="e-new" aria-labelledby="new-h"><div class="wrap"><div class="e-new-head"><span class="eyebrow">{{.t.new_eyebrow}}</span><h2 id="new-h">{{.t.new_arrivals}}</h2></div>
<ul class="e-new-list">{{range .arrivals}}<li><a class="e-new-card" href="/p/{{.id}}{{$.qs}}"><span class="e-new-ph">{{if .image}}<img src="{{.image}}?w=160" alt="" loading="lazy">{{end}}</span><span class="e-new-body"><span class="e-cat">{{.categoryLabel}}</span><span class="tname">{{.name}}</span><span class="price">{{if .from}}{{$.t.from}} {{end}}{{.priceText}}</span></span><span class="e-go" aria-hidden="true"><span class="arr">→</span></span></a></li>{{end}}</ul></div></section>{{end}}
