scripts.home:
// GET /?c=Category&q=search&lang=ar
function handle(req) {
  const lang = langOf(req), t = texts(lang);
  const c = req.query.c || '';
  // Search (?q=): name and description in both languages; % and _ are taken literally.
  const q = String(req.query.q || '').trim().slice(0, 60);
  let where = 'active = 1';
  const args = [];
  if (c) { where += ' AND category = ?'; args.push(c); }
  if (q) {
    const like = '%' + q.replace(/[%_\\]/g, '') + '%';
    where += ' AND (name LIKE ? OR name_ar LIKE ? OR description LIKE ? OR description_ar LIKE ?)';
    args.push(like, like, like, like);
  }
  const rows = db.query('SELECT * FROM products WHERE ' + where + ' ORDER BY id', ...args);
  const vs = variantSummary();
  // Category chips: the English category is the filter value, category_ar its Arabic label.
  const cats = db.query('SELECT category, MAX(category_ar) AS category_ar, COUNT(*) AS n FROM products WHERE active = 1 AND category IS NOT NULL AND category != \'\' GROUP BY category ORDER BY MIN(id)');
  return {template: 'home', data: page(req, {products: rows.map(p => Object.assign(localize(p, lang, vs, t), {badgeText: p.badge ? (t['badge_' + p.badge] || '') : ''})),
    categories: cats.map(r => ({value: r.category, label: pick(r, 'category', lang)})), category: c, q: q, ...boutiqueHome(lang, t, cats, rows, vs, c || q)})};
}

// The boutique home (font = boutique): numbers counted from the products, facts from the shop settings, collections with a
// photo and their product count, product badges, new arrivals, a promoted coupon and up to three real client quotes.
function boutiqueHome(lang, t, cats, rows, vs, filtered) {
  const s = store();
  if (!theme(s).boutique) return {};
  const all = filtered ? db.query('SELECT * FROM products WHERE active = 1 ORDER BY id') : rows;
  const families = cats.map(r => {
    const p = db.query("SELECT image FROM products WHERE active = 1 AND category = ? AND image IS NOT NULL AND image != '' ORDER BY id LIMIT 1", r.category)[0];
    return {value: r.category, label: pick(r, 'category', lang), image: p ? p.image : '', n: r.n};
  });
  const now = new Date().toISOString().replace('T', ' ').slice(0, 19);
  const cp = db.query("SELECT * FROM coupons WHERE active = 1 AND promote = 1 AND (expires IS NULL OR expires = '' OR expires > ?) AND (max_uses IS NULL OR max_uses = 0 OR uses < max_uses) ORDER BY id LIMIT 1", now)[0];
  let promo = null;
  if (cp) {
    const shot = all.find(r => r.badge === 'bestseller' && r.image) || all.find(r => r.image);
    promo = {big: (cp.kind === 'percent' ? cp.value + '% ' : amount(cp.value, t) + ' ') + t.off,
      line: t.promo_code.replace('{code}', cp.code) + (cp.min_total > 0 ? ' ' + t.promo_min.replace('{min}', amount(cp.min_total, t)) : ''),
      image: shot ? shot.image : ''};
  }
  // Counted from the shop's own rows; nothing here is typed in.
  const stats = [];
  if (all.length) {
    stats.push({n: all.length, label: t.stat_products, url: '#products'});
    if (cats.length > 1) stats.push({n: cats.length, label: t.stat_families, url: '#families'});
    const low = Math.min(...all.map(p => vs[p.id] ? vs[p.id].min_price : p.price));
    stats.push({n: amount(low, t), label: t.stat_from, url: '#products'});
  }
  // The delivery and payment rules, as checkout applies them.
  const fee = s.delivery_fee || 0, over = freeDeliveryOver(s);
  const facts = [{icon: 'truck', label: t.delivery, value: (fee > 0 ? amount(fee, t) : t.free) + ' ' + t.fact_emirates.replace('{n}', EMIRATES.length)}];
  if (over !== null && fee > 0) facts.push({icon: 'gift', label: t.fact_free_label, value: t.fact_free_value.replace('{min}', amount(over, t))});
  const pays = [s.card_enabled ? t.pay_card : '', s.cod_enabled ? t.pay_cod : ''].filter(Boolean);
  if (pays.length) facts.push({icon: 'card', label: t.payment, value: pays.join(' · ')});
  facts.push({icon: 'tag', label: t.fact_prices_label, value: t.vat_included});
  if (s.preorder_days > 0) facts.push({icon: 'clock', label: t.fact_preorder_label,
    value: s.preorder_days === 1 ? t.fact_preorder_one : t.fact_preorder_value.replace('{n}', s.preorder_days)});
  // New arrivals: products marked new first, then the latest added. Only on the full, unfiltered shop with more than one row of products.
  const arrivals = filtered || all.length <= 4 ? [] : all.slice().sort((a, b) => (b.badge === 'new') - (a.badge === 'new') || b.id - a.id).slice(0, 4)
    .map(p => localize(p, lang, vs, t));
  const name = pick(s, 'name', lang) || '';
  let stamp = '';
  while (stamp.length < 44) stamp += name + ' · ' + t.stamp + ' · ';
  return {families: families, promo: promo, stampText: stamp.slice(0, 48), stats: stats, facts: facts, arrivals: arrivals,
    testimonials: db.query('SELECT * FROM testimonials WHERE active = 1 ORDER BY coalesce(position, 99), id DESC LIMIT 3').map(q => ({quote: pick(q, 'quote', lang), name: q.name})),
    eyebrow: pick(s, 'eyebrow', lang) || '', accent: pick(s, 'tagline_accent', lang) || '', intro: pick(s, 'intro', lang) || ''};
}

