// GET /p/:id
function handle(req) {
  const lang = langOf(req), t = texts(lang);
  const rows = db.query('SELECT * FROM products WHERE id = ? AND active = 1', Number(req.params.id));
  if (rows.length === 0) return {template: 'not_found', data: page(req, {}), status: 404};
  const variants = variantsOf(rows[0], lang, t), p = localize(rows[0], lang, variantSummary(), t);
  const s = store();
  const deliveryFact = (freeDeliveryOver(s) !== null ? t.delivery_fact : t.delivery_fact_flat)
    .replace('{fee}', amount(s.delivery_fee, t)).replace('{free}', amount(s.free_delivery_over, t));
  return {template: 'product', data: page(req, {seo: {type: 'Product', name: p.name, description: p.description, image: p.image, price: p.priceNum, soldOut: p.stock <= 0}, title: p.name, product: p, variants: variants, variantsJSON: JSON.stringify(variants), deliveryFact: deliveryFact})};
}

scripts.cart:
// GET /cart: the cart lives in the browser; this page shows it and the checkout form.
function handle(req) {
  // With store.preorder_days set, the earliest date a shopper may choose (dates are in UAE time, UTC+4).
  const minDate = new Date(Date.now() + 4 * 3600 * 1000 + (store().preorder_days || 0) * 86400000).toISOString().slice(0, 10);
  const t = texts(langOf(req)), err = String(req.query.error || '');
  return {template: 'cart', data: page(req, {title: t.cart, error: err.indexOf('error_') === 0 && t[err] ? t[err] : '', minDate: minDate, emirates: emirates(t)})};
}

scripts.api_products:
// GET /api/products?ids=1,2,3 -> current names and prices for the cart page.
function handle(req) {
  const lang = langOf(req);
  // ids: product ids, or "product.variant" for a variant, e.g. ids=1,2.5
  const keys = (req.query.ids || '').split(',').slice(0, 50);
  const out = [];
  for (const key of keys) {
    const [id, v] = key.split('.').map(Number);
    const r = db.query('SELECT * FROM products WHERE id = ? AND active = 1', id);
    if (!r.length) continue;
    const t = texts(lang), p = localize(r[0], lang, null, t);
    p.key = key;
    p.title = p.name;
    if (v) {
      const x = variantsOf(r[0], lang).find(x => x.id === v);
      if (!x) continue;
      p.option = x.name; p.name += ' – ' + x.name; p.price = x.price; p.priceNum = x.priceNum; p.priceText = price(x.priceNum, t); p.stock = x.stock; p.v = v;
    } else if (db.query('SELECT id FROM variants WHERE product_id = ? AND active = 1 LIMIT 1', id).length) {
      continue; // a variant must be chosen
    }
    out.push(p);
  }
  const s = store();
  // The delivery rule's inputs, as deliveryFor reads them: free_delivery_over is null when there is no threshold.
  return {json: {products: out, delivery_fee: s.delivery_fee || 0, free_delivery_over: freeDeliveryOver(s)}};
}

scripts.checkout:
// POST /checkout  form: cart (JSON [{id, qty}]), name, phone, address, emirate, payment (card|cod), lang
// Prices always come from the database, never from the browser.
function handle(req) {
  const lang = req.form.lang === 'ar' ? 'ar' : 'en';
  const q = lang === 'ar' ? '&lang=ar' : '';
  if (!req.user) return {redirect: '/_rx/auth/login?next=' + encodeURIComponent('/cart' + (lang === 'ar' ? '?lang=ar' : ''))};
  const f = req.form;
  const name = (f.name || '').trim(), phone = (f.phone || '').trim(), address = (f.address || '').trim(), emirate = (f.emirate || '').trim();
  if (!name || !phone || !address || !emirate) return {redirect: '/cart?error=error_fields' + q};
  let cart = [];
  try { cart = JSON.parse(f.cart || '[]'); } catch (e) { cart = []; }
  if (!Array.isArray(cart) || cart.length === 0 || cart.length > 50) return {redirect: '/cart?error=error_cart' + q};
  const s = store();
  // Order ahead: with store.preorder_days set, the shopper must choose a date at least that many days from today (UAE time).
  const note = (f.note || '').trim().slice(0, 500);
  let wanted = '';
  if (s.preorder_days > 0) {
    wanted = (f.wanted_date || '').trim();
    const min = new Date(Date.now() + 4 * 3600 * 1000 + s.preorder_days * 86400000).toISOString().slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(wanted) || isNaN(Date.parse(wanted + 'T00:00:00Z')) || wanted < min) return {redirect: '/cart?error=error_date' + q};
  }
  const lines = [];
  let subtotal = 0;
  for (const c of cart) {
    const qty = Math.floor(Number(c.qty));
    const p = db.query('SELECT * FROM products WHERE id = ? AND active = 1', Number(c.id))[0];
    if (!p || !(qty >= 1 && qty <= 99)) return {redirect: '/cart?error=error_cart' + q};
    let line = {id: p.id, name: p.name, name_ar: p.name_ar || '', price: p.price, qty: qty}, stock = p.stock;
    const variants = db.query('SELECT * FROM variants WHERE product_id = ? AND active = 1', p.id);
    if (variants.length) {
      const v = variants.find(x => x.id === Number(c.v));
      if (!v) return {redirect: '/cart?error=error_cart' + q};
      line = {id: p.id, v: v.id, name: p.name + ' – ' + v.name, name_ar: (p.name_ar || p.name) + ' – ' + (v.name_ar || v.name),
        price: v.price === null ? p.price : v.price, qty: qty};
      stock = v.stock;
    }
    if (!(stock >= qty)) return {redirect: '/cart?error=error_cart' + q};
    lines.push(line);
    subtotal += line.price * qty;
  }
  // Discount code: kind 'percent' (value 10 = 10%) or 'amount' (AED off the products).
  let discount = 0, coupon = '';
  const code = (f.coupon || '').trim().toUpperCase();
  if (code) {
    const c = db.query("SELECT * FROM coupons WHERE upper(code) = ? AND active = 1", code)[0];
    const now = new Date().toISOString().replace('T', ' ').slice(0, 19);
    if (!c || (c.expires && c.expires < now) || (c.max_uses && c.uses >= c.max_uses) || (c.min_total && subtotal < c.min_total)) {
      return {redirect: '/cart?error=error_coupon' + q};
    }
    discount = c.kind === 'percent' ? subtotal * c.value / 100 : c.value;
    discount = Math.min(subtotal, Math.round(discount * 100) / 100);
    coupon = c.code;
  }
  const delivery = deliveryFor(s, subtotal);
  const total = Math.round((subtotal - discount + delivery) * 100) / 100;
  const vat = Math.round(total * 5 / 105 * 100) / 100; // prices include 5% VAT
  const method = f.payment === 'card' && s.card_enabled ? 'card' : 'cod';
  if (method === 'cod' && !s.cod_enabled) return {redirect: '/cart?error=error_payment' + q};
  const o = db.exec(`INSERT INTO orders (user_id, customer_name, phone, email, address, emirate, payment_method, status, items, subtotal, delivery, vat, total, lang, discount, coupon, wanted_date, note)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    req.user.id, name, phone, req.user.email || '', address, emirate, method, method === 'cod' ? 'cod' : 'pending', JSON.stringify(lines),
    subtotal, delivery, vat, total, lang, discount, coupon, wanted, note);
  const id = o.lastInsertId;
  if (coupon) db.exec('UPDATE coupons SET uses = coalesce(uses, 0) + 1 WHERE code = ?', coupon);
  restock(lines, -1);
  if (method === 'cod') {
    const o = db.query('SELECT * FROM orders WHERE id = ?', id)[0];
    confirmOrder(o, req.origin + '/orders/' + id);
    try {
      notify.owner({subject: 'New order #' + id + ' (cash on delivery): AED ' + money(total) + (wanted ? ', for ' + wanted : ''),
        text: lines.map(l => l.qty + ' x ' + l.name).join('\n') + '\n\nCustomer: ' + name + ', ' + phone + '\nAddress: ' + address + ', ' + emirate +
          (wanted ? '\nWanted on: ' + wanted : '') + (note ? '\nNote: ' + note : '')});
    } catch (e) { console.warn('owner not notified: ' + e); }
    return {redirect: '/orders/' + id + '?placed=1' + q};
  }
  let items = lines.map(l => ({name: l.name, price: l.price, quantity: l.qty}));
  if (delivery > 0) items.push({name: 'Delivery', price: delivery, quantity: 1});
  if (discount > 0) items = [{name: 'Order #' + id + ' (' + coupon + ' applied)', price: total, quantity: 1}];
  try {
    const pay = payments.checkout({items: items, reference: 'order-' + id, customer_email: req.user.email || '',
      success_path: '/orders/' + id + '?placed=1' + q, cancel_path: '/orders/' + id + (lang === 'ar' ? '?lang=ar' : '')});
    return {redirect: pay.url};
  } catch (e) {
    console.error('checkout failed for order ' + id + ': ' + e);
    db.exec("UPDATE orders SET status = 'failed' WHERE id = ?", id);
    restock(lines, 1);
    return {redirect: '/cart?error=error_payment' + q};
  }
}

scripts.pay_again:
// POST /orders/:id/pay: retry a card payment that was not completed.
function handle(req) {
  const lang = req.form.lang === 'ar' ? 'ar' : 'en';
  const o = db.query('SELECT * FROM orders WHERE id = ? AND user_id = ?', Number(req.params.id), req.user.id)[0];
  if (!o || o.status !== 'pending') return {redirect: '/orders/' + req.params.id + (lang === 'ar' ? '?lang=ar' : '')};
  let items = JSON.parse(o.items).map(l => ({name: l.name, price: l.price, quantity: l.qty}));
  if (o.delivery > 0) items.push({name: 'Delivery', price: o.delivery, quantity: 1});
  if (o.discount > 0) items = [{name: 'Order #' + o.id + ' (' + o.coupon + ' applied)', price: o.total, quantity: 1}];
  const q = lang === 'ar' ? '&lang=ar' : '';
  const pay = payments.checkout({items: items, reference: 'order-' + o.id, customer_email: o.email,
    success_path: '/orders/' + o.id + '?placed=1' + q, cancel_path: '/orders/' + o.id + (lang === 'ar' ? '?lang=ar' : '')});
  return {redirect: pay.url};
}

