scripts.invoice:
// GET /orders/:id/invoice (signed in; own orders). Prices include 5% VAT, so each line is split into its parts.
function handle(req) {
  const lang = langOf(req), t = texts(lang), s = store();
  const o = db.query('SELECT * FROM orders WHERE id = ? AND user_id = ?', Number(req.params.id), req.user.id)[0];
  if (!o || o.status === 'pending') return {template: 'not_found', data: page(req, {}), status: 404};
  const split = (gross) => { const net = Math.round(gross / 1.05 * 100) / 100; return {net: net, vat: Math.round((gross - net) * 100) / 100}; };
  const rows = JSON.parse(o.items).map(l => {
    const unit = split(l.price), line = split(l.price * l.qty);
    return {name: lineName(l, lang), qty: l.qty, unit: money(unit.net), vat: money(line.vat), total: money(l.price * l.qty)};
  });
  if (o.discount > 0) { const d = split(o.discount); rows.push({name: t.discount + ' (' + o.coupon + ')', qty: 1, unit: '-' + money(d.net), vat: '-' + money(d.vat), total: '-' + money(o.discount)}); }
  if (o.delivery > 0) { const d = split(o.delivery); rows.push({name: t.delivery, qty: 1, unit: money(d.net), vat: money(d.vat), total: money(o.delivery)}); }
  const totals = split(o.total);
  return {template: 'invoice', data: page(req, {inv: {id: o.id, date: longDate(o.created_at, t), title: s.trn ? t.tax_invoice : t.invoice,
    seller: pick(s, 'legal_name', lang) || pick(s, 'name', lang), sellerAddress: pick(s, 'address', lang) || '', trn: s.trn || '', buyer: o.customer_name,
    buyerAddress: o.address + (lang === 'ar' ? '، ' : ', ') + emirateName(o.emirate, t),
    phone: o.phone, rows: rows, net: price(totals.net, t), vat: price(totals.vat, t), total: price(o.total, t)}})};
}

scripts.on_payment:
// Runs when a card payment is paid, fails or expires. req.body: {event, reference, amount, ...}
function handle(req) {
  const id = Number(String(req.body.reference).replace('order-', ''));
  const o = db.query('SELECT * FROM orders WHERE id = ?', id)[0];
  if (!o) return {text: 'ignored'};
  if (req.body.event === 'refunded' || req.body.event === 'partially_refunded') {
    // A refund made in Stripe: record it on the order; stock is the owner's call.
    db.exec('UPDATE orders SET status = ? WHERE id = ?', req.body.event, id);
    console.log('order ' + id + ' ' + req.body.event + ' ' + req.body.refunded_amount);
    return {text: 'ok'};
  }
  if (o.status !== 'pending') return {text: 'ignored'};
  if (req.body.event === 'paid') {
    db.exec("UPDATE orders SET status = 'paid' WHERE id = ?", id);
    confirmOrder(db.query('SELECT * FROM orders WHERE id = ?', id)[0], req.origin + '/orders/' + id);
  } else {
    // Failed or expired: give the stock back. The visitor can still pay again from the order page while it is pending.
    db.exec('UPDATE orders SET status = ? WHERE id = ?', req.body.event, id);
    restock(JSON.parse(o.items), 1);
  }
  console.log('order ' + id + ' payment ' + req.body.event);
  return {text: 'ok'};
}

scripts.mcp_search:
// MCP tool: shoppers' AI assistants search the catalog. req.body: {query, category, lang}
function handle(req) {
  const lang = req.body.lang === 'ar' ? 'ar' : 'en';
  const q = '%' + String(req.body.query || '').trim() + '%';
  const cat = String(req.body.category || '').trim();
  const rows = db.query(`SELECT * FROM products WHERE active = 1 AND (name LIKE ? OR name_ar LIKE ? OR description LIKE ? OR description_ar LIKE ? OR category LIKE ? OR category_ar LIKE ?)
    AND (? = '' OR category = ? OR category_ar = ?) ORDER BY id LIMIT 20`, q, q, q, q, q, q, cat, cat, cat);
  const vs = variantSummary();
  const suffix = lang === 'ar' ? '?lang=ar' : '';
  return {json: {currency: 'AED', prices_include_vat: true, products: rows.map(p => {
    const l = localize(p, lang, vs);
    return {id: l.id, name: l.name, category: l.categoryLabel, price: l.priceNum, price_is_from: l.from, in_stock: l.stock > 0, has_options: l.hasVariants,
      url: req.origin + '/p/' + l.id + suffix, image: l.image ? req.origin + l.image + '?w=480' : null};
  }), categories: db.query("SELECT category, MAX(category_ar) AS category_ar FROM products WHERE active = 1 AND category IS NOT NULL AND category != '' GROUP BY category ORDER BY category").map(r => pick(r, 'category', lang))}};
}

