scripts.daily_report:
// Job: every evening, email (and WhatsApp, if turned on) the owner a summary of today's orders.
// created_at is UTC; the day is counted from midnight in Dubai (UTC+4).
function handle(req) {
  const dubai = new Date(Date.now() + 4 * 3600 * 1000);
  const midnight = Date.UTC(dubai.getUTCFullYear(), dubai.getUTCMonth(), dubai.getUTCDate()) - 4 * 3600 * 1000;
  const since = new Date(midnight).toISOString().replace('T', ' ').slice(0, 19);
  const rows = db.query(`SELECT status, payment_method, COUNT(*) AS n, SUM(total) AS total FROM orders WHERE created_at >= ? GROUP BY status, payment_method`, since);
  // Orders made ahead that are wanted tomorrow, for stores with store.preorder_days set.
  const tomorrow = new Date(dubai.getTime() + 86400000).toISOString().slice(0, 10);
  const ahead = db.query("SELECT id, customer_name, items, note FROM orders WHERE wanted_date = ? AND status IN ('paid', 'cod') ORDER BY id LIMIT 50", tomorrow);
  const aheadText = ahead.map(o => '#' + o.id + ' ' + o.customer_name + ': ' + JSON.parse(o.items).map(l => l.qty + ' x ' + l.name).join(', ') + (o.note ? ' (' + o.note + ')' : '')).join('\n');
  if (rows.length === 0 && ahead.length === 0) return {text: 'no orders today'};
  if (rows.length === 0) {
    notify.owner({subject: 'Tomorrow: ' + ahead.length + ' order' + (ahead.length === 1 ? '' : 's') + ' to prepare', text: aheadText});
    return {text: ahead.length + ' orders for tomorrow reported'};
  }
  let count = 0, sum = 0;
  const lines = rows.map(r => {
    count += r.n;
    if (r.status === 'paid' || r.status === 'cod' || r.status === 'shipped' || r.status === 'delivered') sum += r.total;
    return r.n + ' x ' + r.status + ' (' + r.payment_method + '): AED ' + money(r.total);
  });
  const low = db.query('SELECT name, stock FROM products WHERE active = 1 AND stock <= 3 ORDER BY stock LIMIT 10');
  let text = lines.join('\n');
  if (low.length) text += '\n\nLow stock:\n' + low.map(p => p.name + ': ' + p.stock).join('\n');
  if (ahead.length) text += '\n\nTo prepare for tomorrow (' + tomorrow + '):\n' + aheadText;
  notify.owner({subject: 'Today: ' + count + ' order' + (count === 1 ? '' : 's') + ', AED ' + money(sum) + ' paid or cash on delivery', text: text});
  return {text: count + ' orders reported'};
}

scripts.manifest:
// GET /manifest.webmanifest: lets shoppers add the shop to their phone's home screen, in the shop's name and colour.
function handle(req) {
  const s = store(), th = theme(s), lang = langOf(req), name = pick(s, 'name', lang) || 'Shop';
  const icons = th.logo ? [{src: th.logo + '?w=320', sizes: '320x320', purpose: 'any'}, {src: th.logo + '?w=640', sizes: '640x640', purpose: 'any'}] : [];
