}

lib.common:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function store() { return db.query('SELECT * FROM store ORDER BY id LIMIT 1')[0]; }
// The delivery rule, in one place. store.free_delivery_over above 0 makes delivery free from that subtotal on;
// 0 or empty means there is no threshold and store.delivery_fee is always charged. The cart page's script
// mirrors deliveryFor with what /api/products returns.
function freeDeliveryOver(s) { return s.free_delivery_over > 0 ? s.free_delivery_over : null; }
function deliveryFor(s, subtotal) { const over = freeDeliveryOver(s); return over !== null && subtotal >= over ? 0 : (s.delivery_fee || 0); }
function money(n) { return (Math.round((n || 0) * 100) / 100).toFixed(2); }
// An amount with its currency in the page's language, from texts.money: "AED 250.00" or "250.00 د.إ".
function price(n, t) { return (t.money || 'AED {n}').replace('{n}', money(n)); }
// The same for notes and sentences: whole amounts without decimals ("AED 200"), kept on one line.
function amount(n, t) { const v = Math.round((n || 0) * 100) / 100; return (t.money || 'AED {n}').replace('{n}', v % 1 === 0 ? String(v) : v.toFixed(2)).replace(/ /g, '\u00a0'); }
// 'YYYY-MM-DD' as "19 Nov 2026" or "19 نوفمبر 2026" (month names from texts.months, Western digits).
function longDate(ymd, t) {
  const p = String(ymd || '').slice(0, 10).split('-'), m = String(t.months || '').split('|');
  if (p.length !== 3 || m.length !== 12) return String(ymd || '');
  return Number(p[2]) + ' ' + m[Number(p[1]) - 1] + ' ' + p[0];
}
// The Arabic value of a column pair such as name / name_ar, or the English one when there is none.
function pick(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }
// The current address in the other language, keeping the other query parameters (category, error).
function langLink(req, lang) {
  const q = [];
  for (const k in req.query) if (k !== 'lang') q.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  if (lang === 'ar') q.push('lang=ar');
  return req.path + (q.length ? '?' + q.join('&') : '');
}
function page(req, extra) {
  const lang = langOf(req), s = store(), t = texts(lang);
  const qs = lang === 'ar' ? '?lang=ar' : '';
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: t, user: req.user,
    store: s, theme: theme(s), storeName: pick(s, 'name', lang), tagline: pick(s, 'tagline', lang), story: pick(s, 'story', lang) || '', address: pick(s, 'address', lang) || '',
    path: req.path, qs: qs, amp: lang === 'ar' ? '&lang=ar' : '', here: req.path + qs,
    langEn: langLink(req, 'en'), langAr: langLink(req, 'ar'), wa: (s.whatsapp || '').replace(/[^0-9]/g, ''),
    freeOver: freeDeliveryOver(s) !== null,
    // The boutique footer lists the categories and the payment methods that are switched on.
    footCats: theme(s).boutique ? db.query("SELECT category, MAX(category_ar) AS category_ar FROM products WHERE active = 1 AND category IS NOT NULL AND category != '' GROUP BY category ORDER BY MIN(id) LIMIT 6").map(r => ({value: r.category, label: pick(r, 'category', lang)})) : [],
    payNote: [s.card_enabled ? t.pay_card : '', s.cod_enabled ? t.pay_cod : ''].filter(Boolean).join(' · '),
    shipNote: freeDeliveryOver(s) !== null ? t.free_delivery_over + ' ' + amount(s.free_delivery_over, t) : t.delivery + ' ' + amount(s.delivery_fee, t)};
  for (const k in extra) base[k] = extra[k];
  base.seo = seoOf(req, base, s, 'Store', base.seo);
  return base;
}

// What search engines, link previews (WhatsApp, Instagram) and AI assistants read in <head>: the page's
// description and picture, and schema.org data. The home page describes the business (kind is its
// schema.org type); a detail page passes item: {type, name, description, image, price, soldOut}.
// The platform adds the canonical address, the other Open Graph tags and the hreflang links itself.
function seoOf(req, d, s, kind, item) {
  const abs = u => !u ? '' : /^https?:\/\//.test(u) ? u : req.origin + u;
  const short = x => { x = String(x || '').replace(/\s+/g, ' ').trim(); return x.length > 160 ? x.slice(0, 159) + '…' : x; };
  const here = req.origin + req.path + (d.lang === 'ar' ? '?lang=ar' : ''), name = pick(s, 'name', d.lang) || '';
  const out = {description: short(d.tagline || d.story), image: abs(s.hero_image || s.logo), icon: abs(s.logo)};
  const put = (o, k, v) => { if (v) o[k] = v; };
  if (item && item.name) {
    out.description = short(item.description) || out.description;
    out.image = abs(item.image) || out.image;
    const j = {'@context': 'https://schema.org', '@type': item.type || 'Product', name: item.name, url: here};
    put(j, 'description', short(item.description));
    put(j, 'image', abs(item.image));
    if (item.type === 'Service') j.provider = {'@type': kind, name: name};
    if (item.price > 0) j.offers = {'@type': 'Offer', price: Number(item.price).toFixed(2), priceCurrency: 'AED', url: here,
      availability: 'https://schema.org/' + (item.soldOut ? 'OutOfStock' : 'InStock')};
    out.jsonld = j;
  } else if (req.path === '/') {
    const j = {'@context': 'https://schema.org', '@type': kind, name: name, url: here};
    put(j, 'description', out.description);
    put(j, 'image', out.image);
    put(j, 'logo', out.icon);
    put(j, 'telephone', s.phone || s.whatsapp);
    put(j, 'address', d.address);
    out.jsonld = j;
  }
  return out;
}

lib.shop:
// The seven emirates: the value stored on the order is the English name, the label comes from texts (emirate_dubai, ...).
const EMIRATES = ['Dubai', 'Abu Dhabi', 'Sharjah', 'Ajman', 'Umm Al Quwain', 'Ras Al Khaimah', 'Fujairah'];
function emirateKey(name) { return 'emirate_' + String(name).toLowerCase().replace(/ /g, '_'); }
function emirates(t) { return EMIRATES.map(e => ({value: e, label: t[emirateKey(e)] || e})); }
function emirateName(name, t) { return t[emirateKey(name)] || name; }
// The name of an order line in the order's language (lines keep name and name_ar from checkout).
function lineName(l, lang) { return lang === 'ar' && l.name_ar ? l.name_ar : l.name; }
// Emails the buyer a confirmation in the order's language, and is quiet on failure.
function confirmOrder(o, link) {
  if (!o.email) return;
  const lang = o.lang === 'ar' ? 'ar' : 'en', t = texts(lang), s = store();
  const fill = (x) => x.replace(/\{id\}/g, o.id).replace(/\{store\}/g, pick(s, 'name', lang))
    .replace(/\{total\}/g, price(o.total, t)).replace(/\{payment\}/g, o.payment_method === 'cod' ? t.pay_cod : t.pay_card)
    .replace(/\{address\}/g, o.address).replace(/\{emirate\}/g, emirateName(o.emirate, t)).replace(/\{link\}/g, link + (lang === 'ar' ? '?lang=ar' : ''));
  try { email.send({to: o.email, subject: fill(t.email_subject), text: fill(t.email_body)}); } catch (e) { console.warn('confirmation not sent: ' + e); }
}
// vs is variantSummary(): products with variants show the lowest price and the stock of all their variants.
// t (texts) adds the shopper-facing strings: priceText, categoryLabel and stockText.
function localize(p, lang, vs, t) {
  const v = vs && vs[p.id];
  const amount = v ? v.min_price : p.price;
  const stock = v ? v.stock : p.stock;
  const out = {id: p.id, name: pick(p, 'name', lang), description: pick(p, 'description', lang),
    category: p.category, categoryLabel: pick(p, 'category', lang), price: money(amount), priceNum: amount, image: p.image, images: [p.image, p.image2, p.image3].filter(Boolean), stock: stock,
    hasVariants: !!v, from: !!v && v.min_price !== v.max_price};
  if (t) {
    out.priceText = price(amount, t);
    out.stockText = stock <= 0 ? t.out_of_stock : stock <= 5 ? t.few_left.replace('{n}', stock) : '';
  }
  return out;
}
function variantSummary() {
  const m = {};
  for (const r of db.query(`SELECT v.product_id, SUM(v.stock) AS stock, MIN(coalesce(v.price, p.price)) AS min_price, MAX(coalesce(v.price, p.price)) AS max_price
    FROM variants v JOIN products p ON p.id = v.product_id WHERE v.active = 1 GROUP BY v.product_id`)) m[r.product_id] = r;
  return m;
}
function variantsOf(p, lang, t) {
  return db.query('SELECT * FROM variants WHERE product_id = ? AND active = 1 ORDER BY id', p.id).map(v => {
    const amount = v.price === null ? p.price : v.price;
    return {id: v.id, name: pick(v, 'name', lang), price: money(amount), priceNum: amount, priceText: t ? price(amount, t) : '', stock: v.stock};
  });
}
// Takes stock (sign -1) or gives it back (sign 1) for order lines; lines with v are variants.
function restock(lines, sign) {
  for (const l of lines) {
    if (l.v) db.exec('UPDATE variants SET stock = stock + ? WHERE id = ?', sign * l.qty, l.v);
    else db.exec('UPDATE products SET stock = stock + ? WHERE id = ?', sign * l.qty, l.id);
  }
}

lib.theme:
// Merchant branding from the settings row (brand_color, font, logo), shared by every Renoxium template.
// theme(row) returns {brand, onBrand, brandText, font, style, lux, logo}; the "top" template puts them on <html>
// (data-font, data-style and CSS variables).
// brand: the owner's colour (#rrggbb); when it is empty or not a colour, a quiet slate (or a deep ink for the luxury styles).
// onBrand: white or near-black, whichever reads better on brand (buttons, the intro band).
// brandText: brand darkened until it passes WCAG AA (4.5:1) as text on white, for links and selected states.
// font picks the type pair and the style:
//   modern (IBM Plex Sans + IBM Plex Sans Arabic), classic (Markazi Text headings + IBM Plex), rounded (Rubik): style "standard".
//   heritage (Cormorant Garamond + Jost, Amiri + Noto Naskh Arabic; ivory, antique gold hairlines) and
//   boutique (Gilda Display + DM Sans, Amiri + IBM Plex Sans Arabic; cream paper, terracotta accent, arches): style "standard"
//   with boutique true, so templates keep their layout and may add boutique sections; its look is the boutique template.
//   atelier (Bodoni Moda + Hanken Grotesk, Noto Naskh Arabic + Noto Kufi Arabic; white, near monochrome): style "luxury",
//   which switches to the luxury layout (centred name, full-bleed photo, no boxes, square buttons).
const THEME_DEFAULT_BRAND = '#334155';
const THEME_DEFAULT_INK = '#1f1b17';
const THEME_FONTS = ['modern', 'classic', 'rounded', 'heritage', 'atelier', 'boutique'];
const THEME_DEFAULT_WARM = '#b4643f';
const THEME_LUXURY = ['heritage', 'atelier'];
function themeHex(v) {
  let s = String(v || '').trim().toLowerCase();
  if (/^#?[0-9a-f]{3}$/.test(s)) s = s.replace('#', '').split('').map(c => c + c).join('');
  s = s.replace('#', '');
  return /^[0-9a-f]{6}$/.test(s) ? '#' + s : '';
}
function themeRgb(hex) { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
function themeLum(rgb) {
  const c = rgb.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function themeContrast(a, b) { const x = themeLum(a), y = themeLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function themeToHex(rgb) { return '#' + rgb.map(v => (Math.round(v) < 16 ? '0' : '') + Math.round(v).toString(16)).join(''); }
function theme(row) {
  row = row || {};
  const font = THEME_FONTS.indexOf(row.font) >= 0 ? row.font : 'modern';
  const lux = THEME_LUXURY.indexOf(font) >= 0;
  const boutique = font === 'boutique';
  const brand = themeHex(row.brand_color) || (lux ? THEME_DEFAULT_INK : boutique ? THEME_DEFAULT_WARM : THEME_DEFAULT_BRAND);
  const rgb = themeRgb(brand), white = [255, 255, 255], ink = [26, 23, 22];
  const onBrand = themeContrast(rgb, white) >= themeContrast(rgb, ink) ? '#ffffff' : '#1a1716';
  let text = rgb;
  for (let i = 0; i < 20 && themeContrast(text, white) < 4.5; i++) text = text.map(v => v * 0.9);
  return {brand: brand, onBrand: onBrand, brandText: themeToHex(text), font: font, style: lux ? 'luxury' : 'standard', lux: lux, boutique: boutique, logo: row.logo || ''};
}
